        "title": "پس منظر اور ذوالفقار علی بھٹو کا دورِ حکومت (1971ء - 1977ء)",
        "content": "جنرل یحییٰ خان نے 1970ء میں جو عام انتخابات کرائے تھے ان کے نتیجے میں دو سیاسی پارٹیاں واضح اکثریت کے ساتھ سامنے آئیں۔ مشرقی پاکستان میں شیخ مجیب الرحمن کی عوامی لیگ نے واضح اکثریت حاصل کی اور مغربی پاکستان میں ذوالفقار علی بھٹو کی پاکستان پیپلز پارٹی نے۔ لیکن سیاسی اختلافات اور بیرونی سازشوں کے باعث دسمبر 1971ء میں مشرقی پاکستان ہم سے الگ ہو کر بنگلہ دیش بن گیا۔ اس سانحے کے بعد جنرل یحییٰ خان مستعفی ہوئے اور 20 دسمبر 1971ء کو اقتدار کی باگ ڈور ذوالفقار علی بھٹو کے سپرد کر دی گئی۔\n\n• بحیثیت پہلے سویلین مارشل لاء ایڈمنسٹریٹر:\nذوالفقار علی بھٹو نے 20 دسمبر 1971ء کو ملک کے پہلے سویلین چیف مارشل لاء ایڈمنسٹریٹر اور صدر کی حیثیت سے اقتدار سنبھالا۔ ملک اس وقت شدید بحران کا شکار تھا: بھارت کی قید میں 93 ہزار سے زائد جنگی قیدی تھے، مغربی سرحدوں پر بے یقینی تھی اور معیشت تباہ حال تھی۔ بھٹو نے عوام کا اعتماد بحال کرنے کے لیے فوری اقدامات کیے۔ 20 اپریل 1972ء کو عبوری آئین کے نفاذ کے ساتھ ملک سے مارشل لاء ختم کر دیا گیا۔\n\n• صنعتوں اور مالیاتی اداروں کو قومی تحویل میں لینا (Nationalization):\n2 جنوری 1972ء کو حکومت نے معاشی استحصال کے خاتمے اور دولت کے چند ہاتھوں میں ارتکاز کو روکنے کے لیے 'صنعتی انتظام کا صدارتی آرڈیننس' جاری کیا۔ اس کے تحت 10 بنیادی صنعتی شعبوں کی 31 بڑی صنعتی اکائیوں کو سرکاری تحویل میں لے لیا گیا جن میں لوہا اور فولاد، بھاری مشینری، برقی سامان، موٹر گاڑیاں، کیمیکلز اور سیمنٹ کی صنعتیں شامل تھیں۔ بعد ازاں یکم جنوری 1974ء کو تمام نجی شیڈول بینکوں اور انشورنس کمپنیوں کو بھی قومی ملکیت میں لے لیا گیا۔\n\n• تعلیمی اور زرعی اصلاحات:\n15 مارچ 1972ء کو نئی تعلیمی پالیسی کا اعلان کیا گیا جس کے تحت یکم ستمبر 1972ء کو تمام نجی کالج اور یکم اکتوبر 1972ء کو تمام نجی سکول قومی تحویل میں لے لیے گئے اور میٹرک تک تعلیم مفت کر دی گئی۔ کسانوں کے حقوق کے تحفظ کے لیے یکم مارچ 1972ء کو زرعی اصلاحات نافذ کی گئیں جن کے تحت انفرادی اراضی کی حد 150 ایکڑ نہری یا 300 ایکڑ بارانی مقرر کی گئی اور زائد اراضی بلا معاوضہ کسانوں میں تقسیم کی گئی۔"
