        "title": "1973ء کا متفقہ آئین: پس منظر، خصوصیات اور اسلامی دفعات",
        "content": "مارشل لاء کے خاتمے کے بعد ملک کے لیے ایک مستقل اور متفقہ آئین کی ضرورت شدت سے محسوس کی گئی۔ 17 اپریل 1972ء کو قومی اسمبلی نے تمام سیاسی جماعتوں کے نمائندوں پر مشتمل 25 رکنی آئینی کمیٹی تشکیل دی جس کے چیئرمین عبدالحفیظ پیرزادہ تھے۔ کمیٹی کی انتھک محنت کے بعد تیار کردہ مسودہ 10 اپریل 1973ء کو قومی اسمبلی نے متفقہ طور پر منظور کر لیا اور 14 اگست 1973ء کو ملک میں باقاعدہ نافذ العمل ہوا۔\n\n• 1973ء کے آئین کی اہم خصوصیات:\n1. تحریری اور وفاقی آئین: یہ ایک جامع تحریری دستاویز ہے جو 280 دفعات، 12 ابواب اور 7 گوشواروں پر مشتمل ہے۔ آئین کی رو سے پاکستان چار صوبوں، وفاقی دارالحکومت اور ملحقہ قبائلی علاقوں پر مشتمل ایک وفاق ہے۔\n2. پارلیمانی نظامِ حکومت: آئین کے تحت ملک میں پارلیمانی نظام نافذ کیا گیا جس میں حکومت کا سربراہ وزیر اعظم ہے جو قومی اسمبلی کا قائد ایوان ہوتا ہے، جبکہ صدر مملکت ریاست کا سربراہ ہے۔\n3. دو ایوانی مقننہ (Bicameral Legislature): وفاقی پارلیمنٹ دو ایوانوں پر مشتمل ہے: ایوانِ بالا (سینیٹ) جو صوبوں کی مساوی نمائندگی کی ضمانت دیتا ہے، اور ایوانِ زیریں (قومی اسمبلی) جس میں نمائندگی آبادی کے تناسب سے ہے۔\n4. بنیادی حقوق اور عدلیہ کی آزادی: آئین تمام شہریوں کو بلا امتیاز رنگ و نسل بنیادی شہری و انسانی حقوق فراہم کرتا ہے اور عدلیہ کی مکمل خودمختاری و آزادی کو یقینی بناتا ہے۔\n\n• آئینِ 1973ء کی اسلامی دفعات:\n1. ملک کا سرکاری نام 'اسلامی جمہوریہ پاکستان' رکھا گیا اور اسلام کو ریاست کا سرکاری مذہب قرار دیا گیا۔\n2. صدر اور وزیر اعظم کے لیے مسلمان ہونا اور عقیدہ ختمِ نبوت پر پختہ ایمان رکھنا لازمی قرار دیا گیا۔\n3. آئین کے آغاز میں قراردادِ مقاصد کو بطور دیباچہ شامل کیا گیا (جو بعد میں 1985ء میں آرٹیکل 2-A کے تحت باقاعدہ متن کا حصہ بنا)۔\n4. آئین کی رو سے تمام موجودہ قوانین کو قرآن و سنت کے مطابق ڈھالا جائے گا اور کوئی ایسا قانون وضع نہیں کیا جائے گا جو اسلامی تعلیمات کے منافی ہو۔\n5. اسلامی نظریاتی کونسل (Council of Islamic Ideology) کا قیام عمل میں لایا گیا جو قانون سازی میں اسلامی رہنمائی فراہم کرتی ہے۔\n6. عربی زبان کی تدریس، زکوٰۃ و عشر کا نظام اور اقلیتوں کے حقوق کا تحفظ آئین کا لازمی جزو بنایا گیا۔"
