        "title": "جنرل محمد ضیاء الحق کا دورِ حکومت (1977ء - 1988ء) اور نفاذِ اسلام",
        "content": "مارچ 1977ء کے عام انتخابات کے نتائج پر حزبِ اختلاف کے 9 جماعتی اتحاد (پاکستان قومی اتحاد - PNA) نے دھاندلی کا الزام عائد کر کے ملک گیر تحریک چلائی۔ ملک میں سیاسی تعطل اور بدامنی کے پیش نظر آرمی چیف جنرل محمد ضیاء الحق نے 5 جولائی 1977ء کو مارشل لاء نافذ کر دیا اور آئین کو معطل کر دیا۔ انہوں نے ابتدائی طور پر 90 دن کے اندر انتخابات کرانے کا اعلان کیا لیکن سیاسی حالات کی بنا پر انتخابات ملتوی ہوتے رہے اور ستمبر 1978ء میں انہوں نے باضابطہ طور پر صدرِ پاکستان کا عہدہ سنبھال لیا۔\n\n• نفاذِ اسلام کے لیے عملی اقدامات:\nجنرل ضیاء الحق نے اپنے 11 سالہ دور میں ملک میں اسلامی نظام کے نفاذ کو اپنی اولین ترجیح قرار دیا اور درج ذیل بنیادی اصلاحات نافذ کیں:\n\n1. شرعی عدالتوں کا قیام (10 فروری 1979ء): چاروں ہائی کورٹس میں شرعی بنچ قائم کیے گئے اور مئی 1980ء میں وفاقی شرعی عدالت (Federal Shariat Court) قائم کی گئی جو کسی بھی مروجہ قانون کو قرآن و سنت کی روشنی میں پرکھنے کا اختیار رکھتی ہے۔\n2. حدود آرڈیننس (فروری 1979ء): سرقہ (چوری)، زنا، قذف (جھوٹی تہمت) اور منشیات کے استعمال و خرید و فروخت پر اسلامی سزائیں نافذ کی گئیں۔\n3. زکوٰۃ و عشر آرڈیننس (20 جون 1980ء): بینک کھاتوں سے یکم رمضان المبارک کو 2.5 فیصد کی شرح سے زکوٰۃ کی کٹوتی کا نظام لاگو کیا گیا اور زرعی پیداوار پر عشر نافذ کیا گیا۔ زکوٰۃ کی تقسیم کے لیے مرکزی، صوبائی اور مقامی زکوٰۃ کمیٹیاں بنائی گئیں۔\n4. بلاسود بینکاری: یکم جنوری 1981ء سے نفع و نقصان کی شراکت (Profit & Loss Sharing - PLS) کے کھاتے کھولے گئے اور یکم جولائی 1985ء سے تمام بینکاری نظام کو سود سے پاک کرنے کا عمل شروع ہوا۔\n5. اسلامی تعلیمات کا فروغ: سکولوں اور کالجوں میں اسلامیات اور مطالعہ پاکستان کی تعلیم لازمی قرار دی گئی، دینی مدارس کی اسناد کو یونیورسٹی ڈگریوں کے مساوی تسلیم کیا گیا، اور اسلام آباد میں بین الاقوامی اسلامی یونیورسٹی کا قیام عمل میں لایا گیا۔\n6. نماز باجماعت اور احترامِ رمضان: سرکاری دفاتر اور تعلیمی اداروں میں نماز باجماعت کا اہتمام لازمی قرار دیا گیا اور احترامِ رمضان آرڈیننس کے تحت رمضان المبارک میں کھلے عام کھانے پینے پر پابندی لگائی گئی۔"
