        "title": "محمد خان جونیجو کی وزارتِ عظمیٰ (1985ء - 1988ء) اور جنیوا معاہدہ",
        "content": "فروری 1985ء میں جنرل ضیاء الحق نے غیر جماعتی بنیادوں پر عام انتخابات منعقد کرائے۔ 23 مارچ 1985ء کو سندھ کے معروف سیاستدان محمد خان جونیجو نے ملک کے وزیر اعظم کی حیثیت سے حلف اٹھایا۔ 30 دسمبر 1985ء کو قومی اسمبلی سے آٹھویں آئینی ترمیم کی منظوری کے بعد ملک سے ساڑھے آٹھ سال بعد مارشل لاء کا باقاعدہ خاتمہ ہوا اور بنیادی حقوق بحال ہوئے۔\n\n• جونیجو حکومت کا پانچ نکاتی ترقیاتی پروگرام:\nوزیر اعظم محمد خان جونیجو نے 31 دسمبر 1985ء کو قوم سے خطاب میں ایک جامع پانچ نکاتی ترقیاتی پروگرام کا اعلان کیا:\n1. اسلامی جمہوری نظام کا قیام و استحکام۔\n2. ملک سے ناخواندگی کا خاتمہ اور شرح خواندگی میں اضافے کے لیے 'نئی روشنی سکول' کا قیام۔\n3. دیہی علاقوں کی ترقی اور بنیادی سہولیات (بجلی، سڑکیں، پینے کا صاف پانی اور صحت) کی فراہمی۔\n4. بے روزگاری کا خاتمہ اور نوجوانوں کو روزگار کے مواقع مہیا کرنا۔\n5. رشوت ستانی، بدعنوانی اور ناانصافی کے خلاف سخت اقدامات اور فوری انصاف کی فراہمی۔\n\n• تاریخی جنیوا معاہدہ (14 اپریل 1988ء):\nافغانستان میں سوویت افواج کی آمد کے بعد پاکستان کو شدید سیکورٹی اور مہاجرین کے مسائل درپیش تھے۔ وزیر اعظم محمد خان جونیجو نے تمام سیاسی جماعتوں کو آل پارٹیز کانفرنس میں اعتماد میں لیا۔ اقوام متحدہ کے زیر اہتمام سوئٹزرلینڈ کے شہر جنیوا میں طویل مذاکرات کے بعد 14 اپریل 1988ء کو تاریخی جنیوا معاہدہ طے پایا جس پر پاکستان، افغانستان، امریکہ اور سوویت یونین نے دستخط کیے۔ اس معاہدے کے نتیجے میں سوویت یونین نے 15 مئی 1988ء سے اپنی افواج کا انخلا شروع کیا جو 15 فروری 1989ء کو مکمل ہوا۔\n\n• سانحہ اوجھڑی کیمپ اور حکومت کی برطرفی:\n10 اپریل 1988ء کو راولپنڈی اور اسلام آباد کے درمیان واقع اوجھڑی اسلحہ ڈپو میں خوفناک دھماکے ہوئے جس سے سینکڑوں بے گناہ شہری شہید اور زخمی ہوئے۔ اس سانحے کی تحقیقات پر صدر اور وزیر اعظم کے مابین اختلافات پیدا ہوئے۔ بالاخر 29 مئی 1988ء کو صدر جنرل ضیاء الحق نے آئین کے آرٹیکل 58(2)(b) کے تحت جونیجو حکومت اور قومی اسمبلی کو برطرف کر دیا۔ اس کے کچھ ہی عرصے بعد 17 اگست 1988ء کو بہاولپور کے قریب سی-130 طیارے کے حادثے میں صدر ضیاء الحق جاں بحق ہو گئے۔"
