      "محمد خان جونیجو نے 1985ء تا 1988ء تک ملک کے منتخب وزیر اعظم کے طور پر پانچ نکاتی ترقیاتی پروگرام پر عمل کرایا۔",
      "14 اپریل 1988ء کو تاریخی جنیوا معاہدہ طے پایا جس کے نتیجے میں سوویت افواج نے افغانستان سے انخلا مکمل کیا۔",
