          "answer": "ذوالفقار علی بھٹو نے 20 دسمبر 1971ء کو اقتدار سنبھالنے کے بعد ملک کو معاشی اور سیاسی بحران سے نکالنے کے لیے ہمہ گیر اصلاحات متعارف کرائیں:\n\n1. صنعتی اصلاحات:\n2 جنوری 1972ء کو بھٹو حکومت نے 10 بنیادی شعبوں کی 31 بڑی صنعتیں قومی تحویل میں لیں جن میں لوہا، سیمنٹ، کیمیکلز، اور مشینری شامل تھیں۔ یکم جنوری 1974ء کو تمام نجی بینک اور انشورنس کمپنیاں قومیائی گئیں۔ اس کا مقصد چند امیر خاندانوں کی معاشی اجارہ داری ختم کرنا تھا۔\n\n2. مزدور اصلاحات (لیبر پالیسی 1972ء):\nمزدوروں کے حقوق کے تحفظ کے لیے نئی لیبر پالیسی جاری ہوئی۔ فیکٹریوں کے منافع میں مزدوروں کا حصہ مقرر کیا گیا، بونس اور مفت طبی سہولیات لازمی کی گئیں، اور مالکان کے بلاوجہ نوکری سے نکالنے پر پابندی لگی۔ سوشل سیکورٹی اور اولڈ ایج بینیفٹس سکیم (EOBI) کی بنیاد رکھی گئی۔\n\n3. زرعی اصلاحات:\nیکم مارچ 1972ء کو زرعی اصلاحات کے تحت ملکیتی اراضی کی حد 150 ایکڑ نہری یا 300 ایکڑ بارانی مقرر کی گئی۔ اضافی زمینیں بلا معاوضہ کسانوں میں تقسیم ہوئیں۔ مزارعین کو بے دخل کرنے پر پابندی لگائی گئی اور بیج، کھاد اور آبیانہ کے اخراجات مالکان پر ڈالے گئے۔\n\n4. تعلیمی اصلاحات:\nنئی تعلیمی پالیسی کے تحت ستمبر اور اکتوبر 1972ء میں نجی کالجز اور سکول قومی تحویل میں لیے گئے۔ میٹرک تک تعلیم مفت کر دی گئی اور غریب طلبہ کے لیے وظائف اور ہاسٹل کی سہولیات دی گئیں۔\n\n5. صحت اور پاسپورٹ اصلاحات:\nادویات کی قیمتیں کم رکھنے کے لیے ڈرگ ایکٹ نافذ کیا گیا، اور پاسپورٹ پالیسی کو آسان بنایا گیا جس سے لاکھوں پاکستانی روزگار کے لیے مشرقِ وسطیٰ گئے اور قیمتی زرمبادلہ ملک بھیجا۔"
