          "answer": "1973ء کا آئین پاکستان کی تاریخ کا متفقہ ترین دستور ہے جس کے اہم نکات درج ذیل ہیں:\n\n1. تحریری اور وفاقی دستور:\nیہ 280 دفعات، 12 ابواب اور 7 گوشواروں پر مشتمل تحریری دستاویز ہے۔ یہ ملک کو چاروں صوبوں، اسلام آباد اور ملحقہ قبائلی علاقوں پر مشتمل ایک وفاق قرار دیتا ہے۔\n\n2. پارلیمانی نظام:\nآئین نے ملک میں خالص پارلیمانی جمہوری نظام قائم کیا جس میں چیف ایگزیکٹو وزیر اعظم ہوتا ہے جسے قومی اسمبلی منتخب کرتی ہے اور وہ پارلیمنٹ کو جوابدہ ہوتا ہے۔ صدر ریاست کا سربراہ ہوتا ہے۔\n\n3. دو ایوانی مقننہ:\nپارلیمنٹ دو ایوانوں پر مشتمل ہے: ایوانِ بالا (سینیٹ) جس میں تمام صوبوں کو مساوی نشستیں دی گئی ہیں تاکہ وفاق میں توازن برقرار رہے، اور ایوانِ زیریں (قومی اسمبلی) جس میں آبادی کی بنیاد پر نمائندگی دی گئی ہے۔\n\n4. اسلامی دفعات:\n- ملک کا سرکاری نام اسلامی جمہوریہ پاکستان اور اسلام ریاست کا سرکاری مذہب ہے۔\n- صدر اور وزیر اعظم کے لیے مسلمان ہونا اور عقیدہ ختمِ نبوت پر ایمان لازمی ہے۔\n- کوئی قانون قرآن و سنت کے احکام کے متصادم نہیں بنایا جا سکتا۔\n- اسلامی نظریاتی کونسل قوانین کا جائزہ لیتی ہے۔\n\n5. عدلیہ کی آزادی اور بنیادی حقوق:\nشہریوں کے بنیادی حقوق (آزادی اظہار، مذہبی آزادی، مساوات) کو آئینی تحفظ حاصل ہے اور سپریم کورٹ اور ہائی کورٹس کو عدالتی خودمختاری دی گئی ہے۔"
