          "answer": "مشرقی پاکستان کی علیحدگی کے بعد ملک کو ایک متفقہ اور مستقل آئین کی ضرورت تھی۔ 17 اپریل 1972ء کو قومی اسمبلی نے 25 رکنی آئینی کمیٹی بنائی جس نے تمام سیاسی جماعتوں (پیپلز پارٹی، نیشنل عوامی پارٹی، جمیعت علماء اسلام، مسلم لیگ) کے مشورے سے مسودہ تیار کیا جو 10 اپریل 1973ء کو متفقہ طور پر منظور ہوا اور 14 اگست 1973ء کو نافذ العمل ہوا۔\n\nآئین کی اہم اسلامی دفعات:\n1. مملکت کا سرکاری نام: آئین کے آرٹیکل 1 کے مطابق ملک کا نام 'اسلامی جمہوریہ پاکستان' رکھا گیا اور آرٹیکل 2 میں اسلام کو ریاست کا سرکاری مذہب قرار دیا گیا۔\n2. صدر اور وزیر اعظم کے لیے شرائط: آرٹیکل 41 اور 91 کے تحت صدر اور وزیر اعظم کے لیے مسلمان ہونا، توحید، رسالت اور ختمِ نبوت پر غیر مشروط ایمان رکھنا لازمی قرار دیا گیا۔\n3. قراردادِ مقاصد: آئین کے آغاز میں قراردادِ مقاصد کو بطور دیباچہ شامل کیا گیا جس کی رو سے کائنات میں حاکمیتِ مطلقہ صرف اور صرف اللہ تعالیٰ کی ذاتِ اقدس کے پاس ہے۔\n4. قوانین کی شریعت سے مطابقت: آئین کی دفعہ 227 میں ضمانت دی گئی کہ کوئی بھی قانون قرآن و سنت کے منافی نہیں بنایا جائے گا اور تمام مروجہ قوانین کو اسلامی سانچے میں ڈھالا جائے گا۔\n5. اسلامی نظریاتی کونسل: ایک آئینی کونسل تشکیل دی گئی جو پارلیمنٹ کو قوانین کے اسلامی پہلوؤں پر سفارشات پیش کرتی ہے۔\n6. زکوٰۃ، عشر اور اوقاف: مسلمانوں کو اپنی انفرادی و اجتماعی زندگی قرآن و سنت کے مطابق گزارنے، زکوٰۃ و عشر کا نظام قائم کرنے، اور عربی زبان کو لازمی کرنے کی دفعات شامل کی گئیں۔"
