          "answer": "جنرل ضیاء الحق نے 5 جولائی 1977ء سے 17 اگست 1988ء تک ملک میں اسلامی نظام کے قیام کو اپنی حکومت کا بنیادی مقصد قرار دیا۔ اس سلسلے میں اٹھائے گئے اقدامات درج ذیل ہیں:\n\n1. شرعی عدالتیں: 1979ء میں ہائی کورٹس میں شرعی بنچ اور 1980ء میں وفاقی شرعی عدالت قائم ہوئی۔ اس عدالت نے سود، عائلی قوانین اور حدود کے قوانین کا شرعی جائزہ لیا۔\n2. حدود آرڈیننس: چوری، زنا، قذف اور شراب نوشی پر قرآنی حدود کے مطابق سزائیں نافذ ہوئیں جس سے معاشرتی جرائم میں نمایاں کمی لانے کی کوشش کی گئی۔\n3. زکوٰۃ و عشر کا نظام: 1980ء سے بینک کھاتوں سے یکم رمضان کو 2.5 فیصد زکوٰۃ کاٹی جانے لگی جس سے لاکھوں مستحقین اور بیواؤں کی مالی کفالت کا ادارہ جاتی نظام بنا۔\n4. بلاسود بینکاری: پی ایل ایس (PLS) کھاتے اور اسلامی مشارکہ کا طریقہ متعارف کرایا گیا۔\n5. نظامِ تعلیم کا اسلامائزیشن: اسلامیات اور مطالعہ پاکستان کی تعلیم لازمی قرار دی گئی اور دینی مدارس کے فارغ التحصیل علماء کو ڈگریوں کے مساوی حقوق دیے گئے۔\n\nتنقیدی جائزہ:\nاگرچہ ان اقدامات سے معاشرے میں اسلامی تشخص کو فروغ ملا، تاہم ناقدین کے مطابق بعض اقدامات کے نفاذ میں فرقہ وارانہ حساسیت کو مدنظر نہ رکھنے کی وجہ سے مسلکی اختلافات ابھرے، اور کلاشنکوف کلچر و افغان جنگ نے ان اصلاحات کے مثبت ثمرات کو جزوی طور پر متاثر کیا۔"
