        "id": "3.3",
        "title": "زرعی شعبہ: معیشت میں کردار، اہم فصلیں اور مسائل",
        "content": "پاکستان بنیادی طور پر ایک زرعی ملک ہے۔ کل آبادی کا تقریباً 65 فیصد بالواسطہ یا بلاواسطہ زراعت سے وابستہ ہے، اور مجموعی ملکی پیداوار (GDP) کا تقریباً 19 سے 21 فیصد زراعت سے حاصل ہوتا ہے۔\n\n• اہم زرعی فصلیں:\n1. گندم (Wheat): پاکستان کی سب سے اہم غذائی فصل ہے جو ربیع کے موسم میں کاشت ہوتی ہے۔ پنجاب اور سندھ میں اس کی شاندار پیداوار ہوتی ہے۔\n2. چاول (Rice): اہم غذائی اور قیمتی برآمدی نقد آور فصل ہے۔ پاکستان کا باسمتی چاول اپنی خوشبو اور لمبائی کی وجہ سے دنیا بھر میں مشہور ہے۔\n3. کپاس (Cotton): اسے 'سفید سونا' (White Gold) کہا جاتا ہے۔ یہ ٹیکسٹائل انڈسٹری کی ریڑھ کی ہڈی ہے اور ملک کا سب سے بڑا زرمبادلہ کمانے کا ذریعہ ہے۔\n4. گنا (Sugarcane): شکر اور چینی سازی کی بنیادی فصل ہے جو پنجاب، سندھ اور خیبر پختونخوا میں پیدا ہوتا ہے۔\n5. تمباکو (Tobacco): نقد آور فصل ہے جس کا 75 فیصد حصہ خیبر پختونخوا (مردان، صوابی اور چارسدہ) اور 25 فیصد پنجاب میں پیدا ہوتا ہے۔\n6. جوار، باجرہ، مکئی اور دالیں: انسانی خوراک اور جانوروں کے چارے کے لیے بارانی و نہری علاقوں میں کاشت ہوتی ہیں۔\n\n• زرعی پیداوار میں کمی کے اسباب:\n1. روایتی طریقہ کاشت اور جدید مشینری کی کمی۔\n2. سیم و تھور (Waterlogging & Salinity) کی وجہ سے لاکھوں ایکڑ اراضی کا بنجر ہونا۔\n3. اراضی کا نسل در نسل تقسیم ہو کر چھوٹے چھوٹے ٹکڑوں میں بٹ جانا۔\n4. پانی کی قلت، نہری پانی کا ضیاع اور ناقص بیج و کھادوں کا استعمال۔\n5. کسانوں کی مالی بدحالی اور زرعی قرضوں کی کمی۔"
