        "title": "آبپاشی کا نہری نظام، بیراج، ڈیمز اور کاریز",
        "content": "پاکستان کا نہری نظام دنیا کے عظیم ترین آبپاشی نظاموں میں شمار ہوتا ہے۔ چونکہ ملک کے اکثر علاقوں میں بارش کم ہوتی ہے، اس لیے زراعت کا دارومدار آبپاشی پر ہے:\n\n• آبپاشی کے ذرائع:\n1. نہری نظام (Canals): دریاؤں پر بیراج اور ہیڈ ورکس تعمیر کر کے نہریں نکالی جاتی ہیں۔ مستقل نہریں سال بھر پانی دیتی ہیں جبکہ غیر مستقل نہریں صرف گرمیوں میں سیلابی پانی لاتی ہیں۔\n2. بڑے کثیر المقاصد ڈیمز:\n- تربیلا ڈیم: دریائے سندھ پر تعمیر دنیا کا مٹی کا سب سے بڑا ڈیم ہے جو آبپاشی اور بجلی پیدا کرتا ہے۔\n- منگلا ڈیم: دریائے جہلم پر سندھ طاس معاہدے کے تحت تعمیر ہوا۔\n- وارسک ڈیم: خیبر پختونخوا میں دریائے کابل پر واقع ہے۔\n- گومل زم اور دیامیر بھاشا ڈیمز۔\n3. ٹیوب ویل اور کنویں: نہری پانی کی کمی پوری کرنے اور سیم و تھور کے خاتمے کے لیے زیر زمین پانی نکالتے ہیں۔\n4. کاریز کا روایتی نظام (Karez System):\nبلوچستان کے پہاڑی علاقوں میں پانی کے بخارات بننے سے بچانے کے لیے زیر زمین سرنگوں کے ذریعے پانی چشموں سے کھیتوں تک لایا جاتا ہے۔ یہ صدیوں پرانا شاہکار نظام کاریز کہلاتا ہے۔"
