        "content": "• حیواناتی وسائل (Livestock):\nپاکستان کے زرعی شعبے میں لائیو اسٹاک کا حصہ 60 فیصد سے زائد ہے۔ گائے، بھینس، بھیڑ اور بکریاں دودھ، مکھن اور گوشت فراہم کرتی ہیں جبکہ چمڑا اور اون برآمد کر کے زرمبادلہ کمایا جاتا ہے۔ بیل اور اونٹ بار برداری اور ہل چلانے میں کام آتے ہیں۔ پاکستان دودھ کی پیداوار میں دنیا کے اولین پانچ ممالک میں شامل ہے۔ پولٹری فارمنگ (مرغ بانی) سائنسی بنیادوں پر ترقی کر چکی ہے جو گوشت اور انڈوں کی ملکی ضرورت پوری کرتی ہے۔\n\n• ماہی گیری (Fisheries):\nماہی گیری ساحلی عوام کا اہم ذریعہ روزگار ہے۔ پاکستان کا ساحل 1050 کلومیٹر طویل ہے۔\n- سمندری ماہی گیری: کراچی اور بلوچستان کے ساحل (گوادر، پسنی، اورماڑہ) پر مچھلی اور جھینگا پکڑا جاتا ہے۔\n- میٹھے پانی کی ماہی گیری: دریاؤں، ڈیموں، جھیلوں (منچھر جھیل، کلر کہار) اور فارمز میں مچھلی پالی جاتی ہے۔ مچھلی اور جھینگا برآمد کر کے قیمتی زرمبادلہ کمایا جاتا ہے۔"
