        "title": "پاکستان کی صنعتیں: چھوٹی و گھریلو اور بڑی صنعتیں",
        "content": "تقسیمِ ہند کے وقت برصغیر کے 921 کارخانوں میں سے پاکستان کے حصے میں صرف 34 کارخانے آئے۔ حکومت نے صنعتی ترقی کے لیے پاکستان انڈسٹریل ڈویلپمنٹ کارپوریشن (PIDC) قائم کی۔\n\n• گھریلو اور چھوٹی صنعتیں (Small & Cottage Industries):\nوہ صنعتیں جن میں کاریگر اپنے گھروں یا چھوٹی ورکشاپس میں ہاتھ یا سادہ اوزاروں سے کام کرتے ہیں۔ مجموعی قومی پیداوار میں ان کا حصہ اہم ہے۔\nاہم مثالیں: سیالکوٹ کا کھیلوں کا سامان اور جراحی کے آلات (Surgical Instruments)، گوجرانوالہ کے برتن، گجرات کے پنکھے، ہاتھ سے بنے قالین، کڑھائی اور برتن سازی۔\n\n• بڑی صنعتیں (Large-Scale Industries):\n1. ٹیکسٹائل کی صنعت: پاکستان کی سب سے بڑی صنعت ہے جو کل مینوفیکچرنگ کا 46 فیصد ہے اور لاکھوں افراد کو روزگار دیتی ہے۔ سوتی کپڑا، دھاگہ اور ریڈی میڈ گارمنٹس اہم برآمدات ہیں۔\n2. چینی سازی (Sugar Industry): گنے کی فراہمی پر منحصر ہے اور ملک میں 80 سے زائد شوگر ملز ہیں۔\n3. سیمنٹ کی صنعت: چونا پتھر اور جپسم کی فراوانی کے باعث پاکستان سیمنٹ میں خود کفیل ہے اور اسے برآمد بھی کرتا ہے۔\n4. کیمیائی کھاد: زرعی ضروریات پوری کرنے کے لیے یوریا اور ڈی اے پی کھاد کے بڑے کارخانے قائم ہیں۔\n5. پاکستان اسٹیل ملز کراچی: روس کے تعاون سے قائم ہوئی جس نے لوہے اور اسٹیل کی بنیادی بنیاد رکھی۔"
