        "title": "آبادی کی ترکیب بلحاظِ جنس اور عمر",
        "content": "آبادی کی جنسی اور عمرانی تقسیم کا جائزہ:\n1950ء میں آبادی کے لحاظ سے پاکستان دنیا کا چودھواں بڑا ملک تھا اور 2004ء میں چھٹے نمبر پر آ گیا۔\n\n• صنفی تقسیم (Gender Composition):\n- مرد: 51 فیصد\n- خواتین: 49 فیصد\n\n• عمر کے لحاظ سے آبادی کی تقسیم (Age Composition):\n1. بچوں کا تناسب (14 سال کی عمر تک):\n- لڑکے: 43.1 فیصد\n- لڑکیاں: 43.2 فیصد\n2. کام کاج اور پیداواری عمر (15 سے 64 سال کے درمیان):\n- مرد: 53.3 فیصد\n- خواتین: 53.6 فیصد\n3. معمر اور بزرگ افراد (65 سال اور اس سے اوپر):\n- مرد: 3.6 فیصد\n- خواتین: 3.2 فیصد\n\nیہ اعداد و شمار بتاتے ہیں کہ پاکستان بنیادی طور پر ایک نوجوان ملک ہے جہاں 50 فیصد سے زائد آبادی کام کاج کی عمر میں ہے، جسے انسانی وسائل (Human Capital) میں ڈھال کر ملک کو تیزی سے ترقی دی جا سکتی ہے۔"
