        "content": "پاکستانی معاشرے کی تیز رفتار ترقی میں درج ذیل مسائل بڑی رکاوٹ ہیں:\n\n1. ناخواندگی (Illiteracy):\nتعلیم کی کمی معاشرتی برائیوں کی جڑ ہے۔ پاکستان میں شرحِ خواندگی لگ بھگ 60 فیصد ہے، اور دیہی علاقوں میں بالخصوص خواتین کی خواندگی کی شرح انتہائی کم ہے۔ وسائل کی کمی اور اسکولوں سے محرومی اس کی بڑی وجہ ہے۔\n\n2. صحت کی ناکافی سہولیات:\nآبادی کے تیز اضافے کی وجہ سے ہسپتالوں میں بستروں، ڈاکٹروں، نرسوں اور معیاری ادویات کی شدید قلت ہے۔ دیہی علاقوں میں بنیادی مراکز صحت (BHUs) فعال نہیں ہیں، جس سے بچوں اور ماؤں کی شرح اموات زیادہ ہے۔\n\n3. بیروزگاری اور غربت:\nملک میں سالانہ لاکھوں نوجوان ڈگریاں حاصل کرتے ہیں لیکن معاشی سست روی کی وجہ سے ملازمتیں دستیاب نہیں ہوتیں۔ اس کے نتیجے میں غربت، احساسِ محرومی اور جرائم میں اضافہ ہوتا ہے۔\n\n4. کچی آبادیاں اور شہری مسائل:\nدیہات سے شہروں کی طرف منتقلی کے باعث غیر منصوبہ بند کچی آبادیاں بن چکی ہیں جہاں صاف پانی، صفائی، گیس اور بجلی کی شدید کمی ہے۔\n\n5. چائلڈ لیبر اور صنفی تفریق:\nغربت کے باعث کم عمر بچے تعلیم چھوڑ کر ہوٹلوں، ورکشاپوں اور اینٹوں کے بھٹوں پر محنت مزدوری کرنے پر مجبور ہیں، جبکہ خواتین کو بااختیار بنانے کے عمل میں روایتی رکاوٹیں حائل ہیں۔"
