        "title": "پاکستان کی علاقائی ثقافتیں: پنجابی، پشتون، سندھی اور بلوچی",
        "content": "پاکستان کی علاقائی ثقافتیں ایک خوبصورت گلدستے کی مانند ہیں:\n\n1. پشتون ثقافت (خیبر پختونخوا اور بلوچستان):\nپشتون معاشرہ 'پختون ولی' کے غیر تحریری ضابطہ اخلاق پر مبنی ہے جس میں مہمان نوازی (میلمستیا)، پناہ دینا (ننواتی)، اور غیرت و بہادری مرکزی حیثیت رکھتے ہیں۔ حجرہ (Hujra) اور جرگہ (Jirga) معاشرتی مسائل کے حل اور بیٹھک کے اہم مراکز ہیں۔ خٹک رقص اور روایتی قہوہ پشتون ثقافت کا خاصہ ہے۔\n\n2. پنجابی ثقافت (پنجاب):\nپنجاب زرخیز زمینوں اور محنتی لوگوں کی دھرتی ہے۔ پنجابی ثقافت میں باہمی میل ملاپ، پنجابی کڑاہی، ساگ و مکئی کی روٹی اور لسی کو خاص مقام حاصل ہے۔ جھومر اور بھنگڑا روایتی رقص ہیں، جبکہ لوک داستانیں (ہیر رانجھا، مرزا صاحباں، سسی پنوں) ادب کا قیمتی سرمایہ ہیں۔\n\n3. سندھی ثقافت (سندھ):\nوادی مہران کی سندھی ثقافت امن پسندی اور تصوف کا گہوارہ ہے۔ سندھی اجرک اور سندھی ٹوپی اس ثقافت کا بین الاقوامی تعارف ہیں۔ سندھ کے صوفی بزرگوں نے امن، پیار اور بھائی چارے کا درس دیا۔ سندھی بریانی اور دستکاریاں بے حد مقبول ہیں۔\n\n4. بلوچی ثقافت (بلوچستان):\nبلوچ ثقافت میں قبائلی روایات، مہمان نوازی اور سخاوت کو اولیت حاصل ہے۔ بلوچی شلوار اور دستار کا اپنا وقار ہے۔ خواتین کے لباس پر پیچیدہ شیشہ دوزی اور بلوچی کڑھائی لاجواب ہوتی ہے۔ روایتی سجی (Sajji) بلوچستان کی مشہور ترین ڈش ہے۔ چوپ رقص قبائلی تقریبات کی رونق ہے۔"
