        "id": "4.7",
        "title": "قومی اور علاقائی زبانوں کی تاریخ اور ارتقاء",
        "content": "زبان قوم کے خیالات کے اظہار اور باہمی رابطے کا اہم ترین ذریعہ ہے:\n\n1. قومی زبان: اردو\nاردو ترکی زبان کا لفظ ہے جس کے معنی لشکر کے ہیں۔ یہ برصغیر میں مختلف اقوام (عرب، ایرانی، ترک اور مقامی لوگ) کے میل جول سے وجود میں آئی۔ اس کا رسم الخط عربی و فارسی سے مماثل ہے۔ اردو پاکستان کی قومی زبان اور تمام اکائیوں کے مابین رابطے کی زبان (Lingua Franca) ہے۔ میر، غالب، اقبال اور فیض نے اسے عالمی ادب کا حصہ بنایا۔\n\n2. پشتو زبان:\nپشتو ایک قدیم آریائی زبان ہے۔ امیر کروڑ نے آٹھویں صدی عیسوی میں پشتو کی پہلی نظم لکھی۔ 13ویں صدی میں سلیمان ماکو نے تذکرۃ الاولیاء لکھی۔ پیر روخان (بایزید انصاری)، خوشحال خان خٹک (قومی شاعر)، اور رحمان بابا (عظیم صوفی شاعر) نے پشتو ادب کو بامِ عروج پر پہنچایا۔\n\n3. پنجابی زبان:\nپنجابی ادب میں بابا فرید گنج شکرؒ کے دوہے اور نکتہ آفرین اشعار سنگ میل ہیں۔ سلطان باہوؒ نے سترہویں صدی میں عارفانہ کلام لکھا۔ وارث شاہؒ نے شاہکار مثنوی 'ہیر رانجھا' تصنیف کی۔ بلھے شاہؒ اور میاں محمد بخشؒ نے پنجابی کو لازوال بنا دیا۔\n\n4. سندھی زبان:\nسندھی کی بنیاد قدیم سنسکرت اور پراکرت پر ہے۔ عربوں کی آمد کے بعد اس میں عربی رسم الخط اور الفاظ شامل ہوئے۔ شاہ عبدالطیف بھٹائیؒ (شاہ جو رسالو)، سچل سرمستؒ اور قادر بخش بیدل سندھی کے مایہ ناز شعرا ہیں۔ مرزا قلیچ بیگ نے سندھی میں ناول نویسی کی بنیاد رکھی۔\n\n5. بلوچی زبان:\nبلوچی پر فارسی کا گہرا اثر ہے۔ اس میں رزمیہ نظمیں (قبائلی بہادروں کی داستانیں) ملتی ہیں۔ مست توکلی اور ملا فاضل بلوچی کے مشہور شعرا ہیں۔ اس کا رسم الخط پشتو اور اردو سے مماثل ہے۔\n\n6. براہوی، ہندکو، سرائیکی اور کشمیری زبانیں:\n- براہوی: وادی سندھ کی قدیم دراوڑی زبانوں میں سے ہے۔ ملک داد براہوی اس کے ممتاز شاعر ہیں۔\n- ہندکو: خیبر پختونخوا کے وسیع علاقے (ہزارہ، پشاور، کوہاٹ) میں بولی جاتی ہے۔ ٹیکسلا سے 2000 سال پرانا کتبہ ملا جو ہندکو سے مشابہ ہے۔\n- سرائیکی: جنوبی پنجاب، بہاولپور اور ڈیرہ اسماعیل خان میں بولی جاتی ہے۔ خواجہ غلام فریدؒ اس کے عظیم صوفی شاعر ہیں۔\n- کشمیری: آزاد کشمیر میں بولی جاتی ہے، حبہ خاتون اور محمود گامی اس کے معروف شاعر ہیں۔"
